sys_ux_client_script.script:
/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
    const recs = api.data.look_up_user.results;

    // console.warn(">>>recs=", recs);
    let listGaudi = recs.map(rec => {
        rec.pstnm.value = rec.pstnm.value || "";
        return {
            "id": rec._row_data.uniqueValue,
            "label": rec.rysid.value,
            "sublabel": `${rec.empnum.value}|${rec.name_ja.value}|${rec.pstnm.value}|${rec.affiliation_name.value}`
        };
    });
    // console.debug(">>> evaluateProperty: ListGaudi=", listGaudi);
	return listGaudi;
}
